def link_semifinished(apps, schema_editor):
    """«Делаем сами» сырьё и продукт с тем же названием теперь одно и то же.

    Продукт «Котлет Фирменный» связываем с сырьём «Котлет Фирменный»: что произвели, приходит на склад
    сырья и идёт в рецепт бургера. Рецепт, записанный в карточке сырья, переносим в продукт.
    """
    RawMaterial = apps.get_model("core", "RawMaterial")
    Product = apps.get_model("core", "Product")
    RecipeItem = apps.get_model("core", "RecipeItem")
    MaterialRecipeItem = apps.get_model("core", "MaterialRecipeItem")
    products = {p.name.strip().casefold(): p for p in Product.objects.filter(material=None)}
    for material in RawMaterial.objects.filter(homemade=True):
        if Product.objects.filter(material=material).exists():
            continue
        product = products.pop(material.name.strip().casefold(), None)
        lines = list(MaterialRecipeItem.objects.filter(material=material))
        if product is None:
            if not lines:
                continue
            product = Product.objects.create(name=material.name, price=0, material=material)
        else:
            product.material = material
            product.save(update_fields=["material"])
        if not RecipeItem.objects.filter(product=product).exists():
            for line in lines:
                if line.ingredient_id != material.pk:
                    RecipeItem.objects.create(product=product, material_id=line.ingredient_id, qty=line.qty)


